function normalizeBookKey(title){
  return String(title||'').replace(/[《》]/g,'').replace(/\s*[:：].*$/,'').trim();
}
function getBookDisplayInfo(original,lang=CURRENT_LANG){
  const key=normalizeBookKey(original);
  if(lang==='zh-Hant')return {title:key,type:'original'};
  const item=BOOK_TITLE_DISPLAY[key];
  if(item&&item[lang])return item[lang];
  return {title:key,type:'original'};
}
function getBookDisplayTitle(original,lang=CURRENT_LANG){return getBookDisplayInfo(original,lang).title;}
function bookTranslationLabel(type,lang=CURRENT_LANG){
  if(type!=='exhibition')return '';
  return lang==='ja'?'展示用訳':lang==='en'?'Exhibition translation':'';
}
window.getBookDisplayInfo=getBookDisplayInfo;
window.getBookDisplayTitle=getBookDisplayTitle;
window.bookTranslationLabel=bookTranslationLabel;


function safeGetStorage(key){
  try{return window.localStorage.getItem(key);}catch(err){return null;}
}

function safeSetStorage(key,value){
  try{window.localStorage.setItem(key,value);}catch(err){}
}

function normalizeLang(v){
  if(!v)return null;
  v=String(v).trim().toLowerCase().replace('_','-');
  if(v==='zh'||v==='zh-hant'||v==='zh-tw'||v==='zh-hk'||v.startsWith('zh-hant')||v.startsWith('zh-tw')||v.startsWith('zh-hk'))return 'zh-Hant';
  if(v==='en'||v.startsWith('en-'))return 'en';
  if(v==='ja'||v==='jp'||v==='ja-jp'||v.startsWith('ja-'))return 'ja';
  return null;
}

function isKioskMode(){
  return new URLSearchParams(location.search).get('kiosk')==='1';
}

function resolveInitialLanguage(){
  const params=new URLSearchParams(location.search);
  const fromUrl=normalizeLang(params.get('lang'));
  if(fromUrl)return fromUrl;
  if(isKioskMode())return 'zh-Hant';
  const fromStorage=normalizeLang(safeGetStorage('sustainabilityLang'));
  if(fromStorage)return fromStorage;
  const browserLangs=Array.isArray(navigator.languages)?navigator.languages:[navigator.language];
  for(const candidate of browserLangs){
    const normalized=normalizeLang(candidate);
    if(normalized)return normalized;
  }
  return 'zh-Hant';
}

let CURRENT_LANG=resolveInitialLanguage();

function t(key){return (I18N[CURRENT_LANG]&&I18N[CURRENT_LANG][key])||I18N['zh-Hant'][key]||key;}

function applyLanguage(lang,{syncUrl=true}={}){
  CURRENT_LANG=normalizeLang(lang)||'zh-Hant';
  document.documentElement.lang=LANGUAGE_CONFIG[CURRENT_LANG].htmlLang;
  document.title=LANGUAGE_CONFIG[CURRENT_LANG].title;
  document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;el.textContent=t(key);});
  document.querySelectorAll('[data-i18n-html]').forEach(el=>{const key=el.dataset.i18nHtml;el.innerHTML=t(key);});
  document.querySelectorAll('[data-i18n-attr]').forEach(el=>{
    el.dataset.i18nAttr.split('|').forEach(rule=>{
      const parts=rule.split(':');
      const attr=parts.shift();
      const key=parts.join(':');
      if(attr&&key)el.setAttribute(attr,t(key));
    });
  });
  document.querySelectorAll('.lang-btn').forEach(btn=>{
    const active=btn.dataset.lang===CURRENT_LANG;
    btn.classList.toggle('active',active);
    btn.setAttribute('aria-pressed',String(active));
  });
  const meta=document.querySelector('meta[name="description"]');
  if(meta)meta.setAttribute('content',t('meta.description'));
  document.body.dataset.lang=CURRENT_LANG;
  if(!isKioskMode())safeSetStorage('sustainabilityLang',CURRENT_LANG);
  if(syncUrl){
    const u=new URL(location.href);
    u.searchParams.set('lang',LANGUAGE_CONFIG[CURRENT_LANG].query);
    history.replaceState(null,'',u.pathname+u.search+u.hash);
  }
  window.dispatchEvent(new CustomEvent('languagechange',{detail:{lang:CURRENT_LANG}}));
}

